import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        String digits = line.trim();
        String[] map = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        List<String> current = new ArrayList<>();
        current.add("");
        for (int i = 0; i < digits.length(); i++) {
            String letters = map[digits.charAt(i) - '0'];
            List<String> next = new ArrayList<>();
            for (String prefix : current) {
                for (int j = 0; j < letters.length(); j++) {
                    next.add(prefix + letters.charAt(j));
                }
            }
            current = next;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < current.size(); i++) {
            if (i > 0) sb.append(',');
            sb.append(current.get(i));
        }
        System.out.println(sb.toString());
    }
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        String s = line.trim();
        if (s.startsWith("[")) s = s.substring(1);
        if (s.endsWith("]")) s = s.substring(0, s.length() - 1);
        String[] parts = s.split(",");
        int n = parts.length;
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = Integer.parseInt(parts[i].trim());
        }
        int total = 1 << n;
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        for (int mask = 0; mask < total; mask++) {
            if (mask > 0) sb.append(',');
            sb.append('[');
            boolean first = true;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    if (!first) sb.append(',');
                    sb.append(nums[i]);
                    first = false;
                }
            }
            sb.append(']');
        }
        sb.append(']');
        System.out.println(sb.toString());
    }
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        String[] parts = line.trim().split(";");
        int left = Integer.parseInt(parts[0].trim());
        int right = Integer.parseInt(parts[1].trim());
        int shift = 0;
        while (left < right) {
            left >>= 1;
            right >>= 1;
            shift++;
        }
        System.out.println(left << shift);
    }
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        int idx = line.indexOf(';');
        String a = (idx < 0 ? line : line.substring(0, idx)).trim();
        String b = (idx < 0 ? "" : line.substring(idx + 1)).trim();
        int n = a.length();
        int m = b.length();
        int[] prev = new int[m + 1];
        int[] cur = new int[m + 1];
        for (int j = 0; j <= m; j++) {
            prev[j] = j;
        }
        for (int i = 1; i <= n; i++) {
            cur[0] = i;
            for (int j = 1; j <= m; j++) {
                int cost = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;
                int best = prev[j] + 1;
                if (cur[j - 1] + 1 < best) best = cur[j - 1] + 1;
                if (prev[j - 1] + cost < best) best = prev[j - 1] + cost;
                cur[j] = best;
            }
            int[] tmp = prev;
            prev = cur;
            cur = tmp;
        }
        System.out.println(prev[m]);
    }
}
